"""Build the Phase 4a methods report and exact output-path manifests from machine results."""
import json
from collections import Counter
from common import ROOT, digest, write_json
from parsers import FIRMS, CONTESTS, module


def main():
    inventory = json.loads((ROOT/"data/fulltext/inventory.json").read_text())
    extraction = json.loads((ROOT/"data/fulltext/summary.json").read_text())
    checked = json.loads((ROOT/"data/findings/check.json").read_text())
    stats = [json.loads(p.read_text()) for p in sorted((ROOT/"data/findings/validation").glob("*.json"))]
    stats.sort(key=lambda s:(-s["documents"],s["firm_id"]))
    failures = [json.loads(l) for l in (ROOT/"data/fulltext/failures.jsonl").read_text().splitlines()]
    totals = {"documents":sum(s["documents"] for s in stats),"findings":sum(s["findings"] for s in stats),
              "formal_findings":sum(s["formal_findings"] for s in stats),"by_firm":stats,"version":"phase4a-v1"}
    assert totals["documents"]==inventory["documents"]==checked["documents"]
    write_json(ROOT/"data/findings/summary.json",totals)
    lines = ["# Phase 4a — full text and findings parser framework", "",
             "Generated by `python3 scripts/findings/report.py` from the frozen collection snapshot and parser diagnostics. All figures exclude holdouts. This is development-set summary agreement, not gold-set recall or severity accuracy.", "",
             f"Full-text cache coverage: **{extraction['document_status']['ok']+extraction['document_status']['partial']:,}/{inventory['documents']:,} document occurrences ({extraction['text_cache_percent']:.2f}%)**; {inventory['unique_artifacts']:,} distinct original hashes. Fully processed without unresolved image-page flags: {extraction['document_status']['ok']:,} occurrences ({extraction['fulltext_percent']:.2f}%). {extraction['document_status']['partial']:,} occurrences retain partial/OCR flags and {extraction['document_status']['failed']:,} failed. The successful/partial cache contains {extraction['pages']:,} physical PDF or logical text pages.", "",
             f"Findings output: **{totals['findings']:,} rows**, including {totals['formal_findings']:,} detailed formal finding occurrences. Duplicate source documents retain separate finding occurrences; these are not unique vulnerabilities or deduplicated engagements. There are {len(FIRMS)} dedicated audit-firm modules, {len(CONTESTS)} contest-platform modules and one generic parser. Output files exist for every publisher in the snapshot, including empty files.", "",
             f"Holdout boundary: {inventory['holdout_hashes']} blocked original hashes; {inventory['excluded']['holdout_occurrences']} source occurrences excluded before any original or text is opened. The extractor, sample inspector, parser runner and checker all guard the holdout list. Gold documents were not extracted, inspected, tuned on or included in these statistics. Phase 3's `local-cache/text/` is never read or written by this pipeline.", "",
             "## Reproduce", "", "```sh", "python3 scripts/findings/pipeline.py", "# To intentionally replace the frozen input snapshot with current collections:",
             "python3 scripts/findings/pipeline.py --refresh-inputs", "```", "",
             "`inventory.py` freezes source bytes/hashes and source occurrence identities. Run it only when intentionally refreshing the input snapshot, followed by extraction and parsing. Extraction is content-addressed and resumable; `--retry` forces text regeneration. Partial parser runs use `run.py --firms FIRM_ID ...`. The inspector selects only unblocked snapshot entries (`inspect_samples.py FIRM_ID --index N --parsed`). No network is used by these commands.", "",
             "PDFs use Poppler `pdftotext -layout -enc UTF-8`; text pages are split at Poppler form feeds, with zero-based half-open Unicode character offsets. Markdown keeps original headings, tables and fenced code. HTML becomes text with heading levels and table separators, excluding script/style content. Quantstamp interactive reports are decoded from static JSON string literals with `ast.literal_eval` and `json.loads`; JavaScript is never executed. All report JSON fields are rendered with headings and JSON-pointer spans. Markdown, HTML and static JSON have one logical page, not an invented printed page number.", "",
             "Poppler and Tesseract were initially absent; Ubuntu packages were downloaded and unpacked locally under `local-cache/fulltext/tools/`, leaving the system installation unchanged. `bootstrap_tools.py` unpacks cached packages; `--download` explicitly enables acquisition of the pinned packages. The extraction script selects local binaries/libraries before PATH. Versions and package hashes are recorded in `data/fulltext/toolchain.json`. PyMuPDF diagnoses near-empty PDF pages with image coverage. When Tesseract is available, affected pages receive OCR; otherwise they are flagged `image_only_page_ocr_unavailable`. Sparse-text and block-segmentation retries at 288 DPI also test inverted images, accepting a retry only with at least two words at confidence 35+ and fifteen alphanumeric characters. Retry modes and page outcomes remain in each local page JSON. Encrypted, malformed, missing, hash-mismatched, empty/image-only and unsupported artifacts are explicit failures. Sparse vector-only or partially illegible text can still require manual review; successful text extraction does not establish semantic completeness.", "",
             "## Findings interchange contract", "",
             "`data/findings/<firm_id>.jsonl` follows the findings fields in `schema/README.md` and adds `firm_id`, `sha256`, `severity_original`, `severity_normalized`, `page`, `body_text`, `body_span`, `method` and numeric `confidence`. Alias pairs are identical: `severity_original=severity_raw` and `severity_normalized=severity`. `document_id` exactly reproduces the collector occurrence identity defined in the foundation builder. `finding_id` is a digest of `collect:<firm>` and the extraction source occurrence ID (parent document ID, parser version and start offset). Printed IDs are retained separately, and repeated IDs across review rounds remain separate occurrences.", "",
             "The top-level source receipt identifies the parent `reports.jsonl` metadata row; its canonical row hash and line locator are preserved. `provenance.extraction_record` and its own canonical digest record the derived finding identity and bounds. Each body is an exact slice of the locally cached full text, tied to original and text hashes, pages and offsets. Narratives remain in `body_text`; separate description/recommendation/resolution fields stay null unless separately extracted. No remediation status is inferred from the presence of prose. Native Quantstamp recommendations are distinct from formal findings. Table-only fallback rows are `summary_excerpt`, with lower confidence, and do not enter formal-finding summary comparisons.", "",
             "Severity normalization uses the single publisher/era crosswalk in `schema/severity_map.yaml`, with its identical-content JSON export. Definition-specific Warning, advice, QA/gas and unrated classes follow the reviewed policy; unfamiliar labels remain unknown and are logged. Source spelling/spacing is retained. Crosswalk evidence, residual unknowns, before/after distributions and earlier-audit re-check exclusions are reported in `docs/phase4/severity_map.md`. Confidence is a heuristic extraction-strength score, not a calibrated correctness probability. Rows remain machine-extracted; severity-policy review does not independently validate finding extraction or unique-vulnerability identity.", "",
             "These files are a staged extraction interchange. The current foundation database builder does not import `data/findings/`; no DuckDB or Phase 3 schema/state was changed for this task. A subsequent importer must validate this extraction contract, retain its provenance and join by document identity.", "",
             "## Printed summary agreement", "",
             "Agreement is `matching / comparable` document occurrences. A match requires equality in every explicitly printed severity bucket in the selected aggregate summary. Missing buckets are not invented as zero; C4 high/medium totals do not assert low/gas totals. Formal detail rows are counted independently of the summary extractor. No rows are added, discarded or relabelled to force agreement. The summary extractor uses vertical/horizontal numeric severity tables, contest section totals, and the native Quantstamp report's own summary counts. It does not derive expectations from detail IDs, listing metadata or the parsed rows.", "",
             "No usable numeric summary, conflicting/ambiguous summaries, extraction failures and parser errors are shown separately and excluded from the agreement denominator. For ChainSecurity the front overview counts the complete audit; later open-findings tables are retained as subset evidence. A zero-row parser result without printed zero totals is never evidence of a clean audit. High count agreement can coexist with wrong titles, body bounds or missed/extra findings that cancel numerically; the held-out gold evaluation remains necessary.", "",
             "| Publisher | Parser | Docs | Findings | Match / comparable | Agreement | No counts | Ambiguous | Extraction failures | Parser errors |",
             "|---|---|---:|---:|---:|---:|---:|---:|---:|---:|"]
    compact = ["| Publisher | Match / comparable | Agreement |", "|---|---:|---:|"]
    for s in stats:
        v = s["validations"]
        pct = f"{s['agreement_percent']:.2f}%" if s['agreement_percent'] is not None else "N/A"
        fraction = f"{s['matching_documents']}/{s['comparable_documents']}"
        lines.append(f"| {s['firm_id']} | {s['parser']} | {s['documents']} | {s['findings']} | {fraction} | {pct} | {v.get('no_usable_printed_counts',0)} | {v.get('ambiguous_printed_counts',0)} | {v.get('extraction_failed',0)} | {v.get('parser_error',0)} |")
        compact.append(f"| {s['firm_id']} | {fraction} | {pct} |")
    lines += ["", f"Overall: {checked['summary_matching']:,}/{checked['summary_comparable']:,} comparable occurrences match ({checked['summary_agreement_percent']:.2f}%). This weights documents, not publishers.", "",
              "Per-document proofs, selected counts, parsed counts and mismatch states are in `data/findings/validation/<firm_id>.jsonl`. The checked accounting and evidence-span result is in `data/findings/check.json`.", "",
              "## Parser modules", "", "| Publisher | Rules |", "|---|---|"]
    for firm in FIRMS+CONTESTS:
        lines.append(f"| {firm} | {module(firm).DESCRIPTION} |")
    lines += [f"| Other publishers | {module('generic').DESCRIPTION} |", "", "## Extraction exceptions", "",
              "`data/fulltext/failures.jsonl` is the complete artifact-level failure/partial list. Join SHA-256 to `data/fulltext/input_documents.jsonl` for each affected publisher/source occurrence. `data/fulltext/extractions.jsonl` records successful and unsuccessful artifacts, methods, warnings, pages, text hashes and cache paths.", "",
              "| Exception | Artifacts |", "|---|---:|"]
    for kind,count in sorted(Counter(r.get("error","partial_image_pages") for r in failures).items()):
        lines.append(f"| {kind} | {count} |")
    changes = checked["collection_files_changed_since_snapshot"]+checked["collection_files_new_since_snapshot"]
    lines += ["", "## Snapshot and limitations", "",
              f"The checker found {len(changes)} collection manifests new/changed after the frozen snapshot. They are enumerated in `data/findings/check.json`; refresh the snapshot to incorporate those later edits. The snapshot is not a claim that all concurrent collection work had finished.", "",
              "Extraction coverage includes all in-scope collected artifacts except holdouts; it does not silently discard malformed reports to improve the percentage. Some older C4 reports print low-risk totals but link to issue pages instead of embedding detail entries: these remain mismatches rather than manufactured findings. Count agreement is reported on development data only. OCR flags, zero-row documents, unrecognized severities, summary mismatches and the generic parser's lower-confidence excerpts are review queues. No recall/precision threshold is claimed from aggregate counts.", "",
              "Every source and output file written for Phase 4a is listed in `docs/phase4/files_written.txt`; local cache files and unpacked toolchain paths are additionally listed in `data/fulltext/local_files_written.txt`. Original collected reports, Phase 3's cache and concurrent work are excluded from those manifests.", ""]
    report_path = ROOT/"docs/phase4/parsers.md"
    report_path.parent.mkdir(parents=True,exist_ok=True)
    report_path.write_text("\n".join(lines))
    (ROOT/"data/findings/agreement.md").write_text("\n".join(compact)+"\n")
    # Enumerate only this task's ownership, with every individual generated path.
    files = sorted({str(p.relative_to(ROOT)) for base in ("scripts/findings","data/fulltext","data/findings","docs/phase4")
                    for p in (ROOT/base).rglob("*") if p.is_file() and "__pycache__" not in p.parts and not p.name.endswith(".tmp")})
    files = sorted(set(files+['docs/phase4/files_written.txt','data/fulltext/local_files_written.txt']))
    (ROOT/"docs/phase4/files_written.txt").write_text("\n".join(files)+"\n")
    cache = [str(p.relative_to(ROOT)) for p in sorted((ROOT/"local-cache/fulltext").rglob("*")) if p.is_file()]
    cache += [str(p.relative_to(ROOT)) for p in sorted((ROOT/"local-cache").glob("*.deb"))]
    cache += [str(p.relative_to(ROOT)) for p in sorted((ROOT/"scripts/findings").rglob("*.pyc"))]
    (ROOT/"data/fulltext/local_files_written.txt").write_text("\n".join(cache)+"\n")
    print(json.dumps({"documents":totals["documents"],"findings":totals["findings"],"report":str(report_path.relative_to(ROOT))},indent=2))


if __name__=="__main__":
    main()
